// CartComponent.jsx
import { useSelector, useDispatch } from 'react-redux';
import { addItem, removeItem } from './cartSlice';
import { useState } from 'react';

export default function CartComponent() {
  const { items } = useSelector(state => state.cart);
  const dispatch = useDispatch();
  const [quantityMap, setQuantityMap] = useState({});

  const handleIncrement = (id) => {
    setQuantityMap(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const handleDecrement = (id) => {
    setQuantityMap(prev => {
      const newCount = (prev[id] || 1) - 1;
      if (newCount <= 0) {
        dispatch(removeItem(id));
        const { [id]: _, ...rest } = prev;
        return rest;
      }
      return { ...prev, [id]: newCount };
    });
  };

  const getCartTotal = () => {
    return items.reduce((sum, item) => {
      const quantity = quantityMap[item.id] || 1;
      return sum + (item.price * quantity);
    }, 0);
  };

  return (
    <div className="cart">
      <h2>Shopping Cart</h2>
      {items.length === 0 ? (
        <p>Your cart is empty</p>
      ) : (
        <>
          <ul className="cart-items">
            {items.map(item => (
              <li key={item.id} className="cart-item">
                <img src={item.image} alt={item.name} className="cart-image" />
                <div className="cart-details">
                  <h3>{item.name}</h3>
                  <p>${item.price.toFixed(2)}</p>
                  <div className="quantity-controls">
                    <button onClick={() => handleDecrement(item.id)}>-</button>
                    <span>{quantityMap[item.id] || 1}</span>
                    <button onClick={() => handleIncrement(item.id)}>+</button>
                  </div>
                </div>
                <button onClick={() => dispatch(removeItem(item.id))} className="remove-btn">×</button>
              </li>
            ))}
          </ul>
          <div className="cart-total">
            <strong>Total: ${getCartTotal().toFixed(2)}</strong>
          </div>
        </>
      )}
    </div>
  );
}
